package com.orderflow.notification.service;import com.orderflow.notification.domain.NotificationType;import org.springframework.stereotype.Component;@Component public class NotificationTemplateService{public Template template(NotificationType type){return switch(type){case PAYMENT_SUCCEEDED->new Template("Payment successful","Your payment was completed successfully.");case PAYMENT_FAILED->new Template("Payment failed","We could not complete your payment.");case ORDER_REFUNDED->new Template("Order refunded","Your order refund was completed.");case DELIVERY_ASSIGNED->new Template("Delivery assigned","A delivery agent has been assigned to your order.");case DELIVERY_PICKED_UP->new Template("Order picked up","Your order has been picked up for delivery.");case DELIVERY_OUT_FOR_DELIVERY->new Template("Out for delivery","Your order is on the way.");case DELIVERY_DELIVERED->new Template("Order delivered","Your order has been delivered.");case DELIVERY_FAILED->new Template("Delivery attempt failed","We could not complete the delivery.");case DELIVERY_CANCELLED->new Template("Delivery cancelled","Your delivery was cancelled.");};}public record Template(String title,String message){}}
